Approach: fold the middleware list from the end, each step wrapping the current chain in a closure created by a helper so that `mw` and `nxt` are bound per step. Tests were run against this code.

**`pipeline.py`**

```python
from __future__ import annotations

from collections.abc import Callable, Sequence
from dataclasses import dataclass, field
from functools import reduce


@dataclass
class Request:
    user: str | None
    prompt: str
    trace: list[str] = field(default_factory=list)


@dataclass(frozen=True, slots=True)
class Response:
    status: int
    body: str


Next = Callable[[Request], Response]
Middleware = Callable[[Request, Next], Response]


def build_chain(middlewares: Sequence[Middleware], endpoint: Next) -> Next:
    """First middleware in the sequence is outermost (sees the request first)."""
    def wrap(nxt: Next, mw: Middleware) -> Next:
        return lambda req: mw(req, nxt)
    return reduce(wrap, reversed(middlewares), endpoint)


def tracing(name: str) -> Middleware:
    def mw(req: Request, nxt: Next) -> Response:
        req.trace.append(f"{name}>")
        resp = nxt(req)
        req.trace.append(f"<{name}")
        return resp
    return mw


def require_user(req: Request, nxt: Next) -> Response:
    if req.user is None:
        return Response(401, "unauthenticated")
    return nxt(req)


def max_prompt_chars(limit: int) -> Middleware:
    def mw(req: Request, nxt: Next) -> Response:
        if len(req.prompt) > limit:
            return Response(413, "prompt too long")
        return nxt(req)
    return mw
```

**`test_pipeline.py`**

```python
from pipeline import *


def endpoint(req: Request) -> Response:
    req.trace.append("endpoint")
    return Response(200, req.prompt.upper())


def test_order_outermost_first():
    req = Request("u", "hi")
    build_chain([tracing("a"), tracing("b")], endpoint)(req)
    assert req.trace == ["a>", "b>", "endpoint", "<b", "<a"]


def test_short_circuit_skips_inner():
    req = Request(None, "hi")
    resp = build_chain([tracing("a"), require_user, tracing("b")], endpoint)(req)
    assert resp.status == 401
    assert req.trace == ["a>", "<a"]


def test_three_layers_not_late_bound():
    req = Request("u", "x" * 5)
    resp = build_chain([tracing("a"), max_prompt_chars(3), tracing("b")], endpoint)(req)
    assert resp.status == 413 and req.trace == ["a>", "<a"]


def test_empty_chain_is_endpoint():
    req = Request("u", "ok")
    assert build_chain([], endpoint)(req) == Response(200, "OK")


def test_chain_reusable():
    chain = build_chain([require_user], endpoint)
    assert chain(Request("u", "a")).status == 200
    assert chain(Request(None, "a")).status == 401
```

